describe('Date Picker - Prevent Past Dates Selection', () => {
  beforeEach(() => {
    cy.visit('/booking');
    cy.get('[data-testid="date-picker-input"]').as('datePickerInput');
    cy.get('[data-testid="date-picker-calendar"]').as('datePickerCalendar');
  });

  it('should prevent selection of past dates and display error message', () => {
    const today = new Date();
    const yesterday = new Date(today);
    yesterday.setDate(yesterday.getDate() - 1);
    const yesterdayFormatted = yesterday.toISOString().split('T')[0];

    cy.get('@datePickerInput').click();
    cy.get('@datePickerCalendar').should('be.visible');

    cy.get(`[data-testid="date-${yesterdayFormatted}"]`).should('have.class', 'disabled');
    cy.get(`[data-testid="date-${yesterdayFormatted}"]`).click({ force: true });

    cy.get('[data-testid="date-error-message"]')
      .should('be.visible')
      .and('contain', 'Cannot select past dates');

    cy.get('@datePickerInput').should('have.value', '');
  });

  it('should allow selection of today and future dates', () => {
    const today = new Date();
    const todayFormatted = today.toISOString().split('T')[0];
    const tomorrow = new Date(today);
    tomorrow.setDate(tomorrow.getDate() + 1);
    const tomorrowFormatted = tomorrow.toISOString().split('T')[0];

    cy.get('@datePickerInput').click();
    cy.get('@datePickerCalendar').should('be.visible');

    cy.get(`[data-testid="date-${todayFormatted}"]`).should('not.have.class', 'disabled');
    cy.get(`[data-testid="date-${todayFormatted}"]`).click();

    cy.get('@datePickerInput').should('have.value', todayFormatted);
    cy.get('[data-testid="date-error-message"]').should('not.exist');
  });

  it('should handle month navigation and prevent past dates in previous months', () => {
    cy.get('@datePickerInput').click();
    cy.get('@datePickerCalendar').should('be.visible');

    const currentMonth = new Date().getMonth();
    const currentYear = new Date().getFullYear();

    cy.get('[data-testid="calendar-prev-month"]').click();

    cy.get('[data-testid="calendar-month-year"]').should(
      'contain',
      new Date(currentYear, currentMonth - 1).toLocaleDateString('en-US', { month: 'long', year: 'numeric' })
    );

    cy.get('[data-testid="date-picker-calendar"] [data-testid^="date-"]').each(($dateElement) => {
      cy.wrap($dateElement).should('have.class', 'disabled');
    });
  });

  it('should allow selection of dates 30 days in the future', () => {
    const today = new Date();
    const futureDate = new Date(today);
    futureDate.setDate(futureDate.getDate() + 30);
    const futureDateFormatted = futureDate.toISOString().split('T')[0];

    cy.get('@datePickerInput').click();
    cy.get('@datePickerCalendar').should('be.visible');

    if (futureDate.getMonth() !== today.getMonth()) {
      cy.get('[data-testid="calendar-next-month"]').click();
    }

    cy.get(`[data-testid="date-${futureDateFormatted}"]`).should('not.have.class', 'disabled');
    cy.get(`[data-testid="date-${futureDateFormatted}"]`).click();

    cy.get('@datePickerInput').should('have.value', futureDateFormatted);
    cy.get('[data-testid="date-error-message"]').should('not.exist');
  });

  it('should clear date selection and allow reselection', () => {
    const today = new Date();
    const todayFormatted = today.toISOString().split('T')[0];

    cy.get('@datePickerInput').click();
    cy.get(`[data-testid="date-${todayFormatted}"]`).click();
    cy.get('@datePickerInput').should('have.value', todayFormatted);

    cy.get('[data-testid="date-picker-clear-btn"]').click();
    cy.get('@datePickerInput').should('have.value', '');

    cy.get('@datePickerInput').click();
    cy.get(`[data-testid="date-${todayFormatted}"]`).click();
    cy.get('@datePickerInput').should('have.value', todayFormatted);
  });

  it('should handle edge case of leap year dates', () => {
    const leapYearDate = new Date(2024, 1, 29);
    const leapYearDateFormatted = leapYearDate.toISOString().split('T')[0];

    cy.get('@datePickerInput').click();
    cy.get('@datePickerCalendar').should('be.visible');

    cy.get('[data-testid="calendar-month-year"]').then(($monthYear) => {
      const text = $monthYear.text();
      if (!text.includes('February 2024')) {
        cy.get('[data-testid="calendar-next-month"]').click({ multiple: true });
      }
    });

    cy.get(`[data-testid="date-${leapYearDateFormatted}"]`).should('not.have.class', 'disabled');
    cy.get(`[data-testid="date-${leapYearDateFormatted}"]`).click();
    cy.get('@datePickerInput').should('have.value', leapYearDateFormatted);
  });
});
